@Override public void onPlayerError(PlaybackException error){
  try {
    @ExportException.ErrorCode int errorCode=checkNotNull(ExportException.NAME_TO_ERROR_CODE.getOrDefault(error.getErrorCodeName(),ERROR_CODE_UNSPECIFIED));
    assetLoaderListener.onError(ExportException.createForAssetLoader(error,errorCode));
  } catch (NullPointerException e) {
    // 处理checkNotNull返回null的情况
    assetLoaderListener.onError(new ExportException("Invalid error code", e));
  } catch (IllegalArgumentException e) {
    // 处理createForAssetLoader参数不合法的情况
    assetLoaderListener.onError(new ExportException("Failed to create export exception", e));
  }
}
